app.use(helmet({
  contentSecurityPolicy: { /* tune for your app */ },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  referrerPolicy: { policy: 'no-referrer' },
}));
```

---

### 5. No CORS policy defined (OWASP A05)

Without explicit CORS config, browsers apply same-origin defaults — which is fine until you (or a dev) add `cors()` with no options and accidentally allow `*`. Define it explicitly:

```js
const cors = require('cors');
app.use(cors({
  origin: ['https://app.example.com'],
  methods: ['GET', 'POST'],
  credentials: true,
  maxAge: 600,
}));
```

